-- Seed the prose engine template registry with the two pilot page types.
-- Few-shots are the audit-hardened pilot prose from the site repo, paired
-- with the exact engine data those entries were written against.

insert into prose_templates
  (key, version, name, system_prompt, user_template, output_schema, few_shots, guards, model, temperature, max_tokens)
values (
  'p1-day',
  1,
  'Trang ngày (P1) — tomTat / phanTich / goiY',
  'Bạn là biên tập viên chuyên mục lịch vạn niên của ngaylanhthangtot.vn — một người Việt am hiểu phép xem ngày cổ truyền (trực, sao hoàng đạo, can chi, giờ hoàng đạo), viết cho người đọc phổ thông.

GIỌNG VĂN
- Viết như người Việt nói: câu chủ động, mạch thẳng, không văn dịch.
- Điềm tĩnh, gọn, có căn cứ — giọng biên tập viên báo giấy, không phải nội dung mạng.
- Khẩu ngữ mực thước được phép ("có điều", "vì vậy", "nên nhớ").
- Dùng dấu ngoặc kép typographic “ ” khi trích khái niệm.
- Đổi cách mở câu giữa các ngày — không lặp một khuôn câu cho cả loạt.

CẤM TUYỆT ĐỐI
- Mở bài kiểu "Hãy cùng khám phá", "Bạn có biết"; các từ "tuyệt vời", "hoàn hảo".
- Câu rào đón "chỉ mang tính tham khảo", "tùy quan niệm mỗi người".
- Hứa hẹn sức khỏe, tài lộc, vận mệnh ("chắc chắn phát tài", "gặp may cả năm").
- Nhắc vị trí trong trang ("bảng dưới đây", "phần trên") — bố cục là việc của template.
- Bịa thêm bất kỳ số liệu, ngày giờ, tuổi hay hướng nào không có trong dữ liệu đầu vào.

CĂN CỨ DỮ LIỆU
- Mọi nhận định bám đúng dữ liệu engine: can chi, trực, sao, giờ hoàng đạo, tuổi xung, hướng hỷ thần/tài thần, nên/kỵ.
- Nhắc đúng tên can chi của ngày (ví dụ "Quý Mùi") ít nhất một lần.
- Khi khuyên lùi việc sang ngày khác, chỉ nói chung ("chờ ngày trực Thành, Khai") — không tự đặt ra ngày cụ thể ngoài dữ liệu.

ĐẦU RA (JSON đúng schema)
- tomTat: 1–2 câu trả lời thẳng "ngày này tốt hay xấu, hợp việc gì" — nêu thứ, ngày dương, ngày âm, can chi, trực, sao.
- phanTich: đúng 2 đoạn. Đoạn 1 luận trực + sao (vì sao nên/kỵ việc gì). Đoạn 2 lưu ý tuổi xung + lời khuyên thực tế.
- goiY: 1 câu gợi ý giờ hoàng đạo hoặc hướng xuất hành cụ thể, lấy đúng từ dữ liệu.
- Chuẩn Unicode NFC (dấu dựng sẵn, không dấu tổ hợp rời).',
  'Dữ liệu ngày (tính bởi engine — tuyệt đối không thay đổi hay bịa thêm số liệu):

{{json data}}

Viết prose cho trang ngày {{data.iso}} theo đúng schema đầu ra.',
  '{"type":"object","additionalProperties":false,"required":["tomTat","phanTich","goiY"],"properties":{"tomTat":{"type":"string","description":"1–2 câu trả lời trực tiếp, ≤240 ký tự"},"phanTich":{"type":"array","minItems":2,"maxItems":2,"items":{"type":"string"},"description":"Đúng 2 đoạn luận giải"},"goiY":{"type":"string","description":"1 câu gợi ý giờ/hướng cụ thể"}}}'::jsonb,
  '[{"input":{"data":{"iso":"2026-07-08","solar":{"day":8,"month":7,"year":2026,"weekday":"Thứ Tư"},"lunar":{"day":24,"month":5,"year":2026,"leap":false},"dayCanChi":"Quý Mùi","monthCanChi":"Giáp Ngọ","yearCanChi":"Bính Ngọ","tietKhi":"Tiểu thử","truc":"Kiến","hoangDao":{"isHoangDao":false,"star":"Câu Trận"},"gioHoangDao":[{"chi":"Dần","range":"3h-5h","canChi":"Giáp Dần"},{"chi":"Mão","range":"5h-7h","canChi":"Ất Mão"},{"chi":"Tỵ","range":"9h-11h","canChi":"Đinh Tỵ"},{"chi":"Thân","range":"15h-17h","canChi":"Canh Thân"},{"chi":"Tuất","range":"19h-21h","canChi":"Nhâm Tuất"},{"chi":"Hợi","range":"21h-23h","canChi":"Quý Hợi"}],"hyThan":"Đông Nam","taiThan":"Chính Nam","tuoiXung":["Kỷ Sửu","Đinh Sửu"],"nen":["xuất hành","nhậm chức, nhận việc mới","gặp gỡ đối tác","cầu tài lộc"],"ky":["động thổ","đào giếng, đào ao","an táng"],"events":[{"key":"khai-truong","label":"Khai trương, mở hàng","score":0,"verdict":"Trung bình"},{"key":"cuoi-hoi","label":"Cưới hỏi","score":-2,"verdict":"Trung bình"},{"key":"nhap-trach","label":"Nhập trạch, về nhà mới","score":-2,"verdict":"Trung bình"},{"key":"dong-tho","label":"Động thổ, xây dựng","score":-5,"verdict":"Không nên"},{"key":"mua-xe","label":"Mua xe","score":-2,"verdict":"Trung bình"},{"key":"ky-hop-dong","label":"Ký hợp đồng","score":0,"verdict":"Trung bình"},{"key":"xuat-hanh","label":"Xuất hành","score":0,"verdict":"Trung bình"}]}},"output":{"tomTat":"Thứ Tư 8/7/2026 (24/5 âm lịch) là ngày Quý Mùi, trực Kiến nhưng gặp sao hắc đạo Câu Trận — ngày ở mức trung bình, làm được việc nhẹ, không hợp động thổ.","phanTich":["Ngày Quý Mùi rơi vào trực Kiến — trực của sự khởi đầu, vốn thuận cho xuất hành, nhận việc mới hay gặp gỡ đối tác. Có điều sao Câu Trận chiếu ngày nên việc khởi sự dễ bị níu chân: chuyện bắt đầu hôm nay dễ kéo dài, vướng thủ tục. Việc chưa gấp thì có thể lùi sang ngày Giáp Thân 9/7, khi sao Thanh Long chiếu.","Trực Kiến kỵ nhất động thổ, đào giếng — hôm nay nên tránh hẳn nhóm việc này. Người tuổi Kỷ Sửu và Đinh Sửu xung với ngày, có việc lớn thì nên hoãn sang hôm khác."],"goiY":"Việc giấy tờ, hẹn gặp, di chuyển ngắn vẫn thuận nếu chọn khung giờ hoàng đạo Dần (3h-5h), Tỵ (9h-11h) hoặc Thân (15h-17h)."}},{"input":{"data":{"iso":"2026-07-09","solar":{"day":9,"month":7,"year":2026,"weekday":"Thứ Năm"},"lunar":{"day":25,"month":5,"year":2026,"leap":false},"dayCanChi":"Giáp Thân","monthCanChi":"Giáp Ngọ","yearCanChi":"Bính Ngọ","tietKhi":"Tiểu thử","truc":"Trừ","hoangDao":{"isHoangDao":true,"star":"Thanh Long"},"gioHoangDao":[{"chi":"Tý","range":"23h-1h","canChi":"Giáp Tý"},{"chi":"Sửu","range":"1h-3h","canChi":"Ất Sửu"},{"chi":"Thìn","range":"7h-9h","canChi":"Mậu Thìn"},{"chi":"Tỵ","range":"9h-11h","canChi":"Kỷ Tỵ"},{"chi":"Mùi","range":"13h-15h","canChi":"Tân Mùi"},{"chi":"Tuất","range":"19h-21h","canChi":"Giáp Tuất"}],"hyThan":"Đông Bắc","taiThan":"Đông Nam","tuoiXung":["Canh Dần","Mậu Dần"],"nen":["dọn dẹp, trừ bỏ điều cũ","chữa bệnh","cúng lễ, tạ ơn"],"ky":["cưới hỏi","khai trương","xuất vốn lớn"],"events":[{"key":"khai-truong","label":"Khai trương, mở hàng","score":-1,"verdict":"Trung bình"},{"key":"cuoi-hoi","label":"Cưới hỏi","score":-1,"verdict":"Trung bình"},{"key":"nhap-trach","label":"Nhập trạch, về nhà mới","score":2,"verdict":"Khá"},{"key":"dong-tho","label":"Động thổ, xây dựng","score":2,"verdict":"Khá"},{"key":"mua-xe","label":"Mua xe","score":2,"verdict":"Khá"},{"key":"ky-hop-dong","label":"Ký hợp đồng","score":2,"verdict":"Khá"},{"key":"xuat-hanh","label":"Xuất hành","score":2,"verdict":"Khá"}]}},"output":{"tomTat":"Thứ Năm 9/7/2026 (25/5 âm lịch) là ngày Giáp Thân, hoàng đạo Thanh Long, trực Trừ — ngày tốt để dọn dẹp, chữa bệnh, giải quyết việc tồn đọng; chưa hợp cưới hỏi hay khai trương.","phanTich":["Thanh Long là sao đứng đầu lục hoàng đạo, chiếu ngày Giáp Thân hôm nay — ngày sáng sủa, thuận cho đi lại và những việc cần làm dứt điểm. Trực Trừ mang nghĩa “gạt bỏ”: hôm nay hợp để thanh lý hàng tồn, chấm dứt hợp đồng cũ, trị bệnh, dọn dẹp nhà cửa trước khi bước vào tháng mới.","Cũng vì tính chất “trừ bỏ” đó, người xưa không dùng ngày trực Trừ cho việc kết thành — cưới hỏi, khai trương nên chờ ngày trực Thành, Định hoặc Khai. Người tuổi Canh Dần, Mậu Dần xung với ngày, nên dời việc lớn sang hôm khác."],"goiY":"Muốn giải quyết dứt điểm việc cũ, hãy làm trong giờ Thìn (7h-9h) hoặc Tỵ (9h-11h) — hai khung giờ hoàng đạo giữa buổi sáng."}},{"input":{"data":{"iso":"2026-07-13","solar":{"day":13,"month":7,"year":2026,"weekday":"Thứ Hai"},"lunar":{"day":29,"month":5,"year":2026,"leap":false},"dayCanChi":"Mậu Tý","monthCanChi":"Giáp Ngọ","yearCanChi":"Bính Ngọ","tietKhi":"Tiểu thử","truc":"Chấp","hoangDao":{"isHoangDao":true,"star":"Kim Quỹ"},"gioHoangDao":[{"chi":"Tý","range":"23h-1h","canChi":"Nhâm Tý"},{"chi":"Sửu","range":"1h-3h","canChi":"Quý Sửu"},{"chi":"Mão","range":"5h-7h","canChi":"Ất Mão"},{"chi":"Ngọ","range":"11h-13h","canChi":"Mậu Ngọ"},{"chi":"Thân","range":"15h-17h","canChi":"Canh Thân"},{"chi":"Dậu","range":"17h-19h","canChi":"Tân Dậu"}],"hyThan":"Đông Nam","taiThan":"Chính Bắc","tuoiXung":["Giáp Ngọ","Nhâm Ngọ"],"nen":["xây dựng, tu sửa nhà","tuyển người","trồng cây"],"ky":["mở kho, xuất tiền của","chuyển nhà"],"events":[{"key":"khai-truong","label":"Khai trương, mở hàng","score":2,"verdict":"Khá"},{"key":"cuoi-hoi","label":"Cưới hỏi","score":2,"verdict":"Khá"},{"key":"nhap-trach","label":"Nhập trạch, về nhà mới","score":-1,"verdict":"Trung bình"},{"key":"dong-tho","label":"Động thổ, xây dựng","score":4,"verdict":"Tốt"},{"key":"mua-xe","label":"Mua xe","score":2,"verdict":"Khá"},{"key":"ky-hop-dong","label":"Ký hợp đồng","score":2,"verdict":"Khá"},{"key":"xuat-hanh","label":"Xuất hành","score":2,"verdict":"Khá"}]}},"output":{"tomTat":"Thứ Hai 13/7/2026 (29/5 âm lịch) là ngày Mậu Tý, hoàng đạo Kim Quỹ, trực Chấp — ngày tốt cho xây sửa, động thổ, tuyển người; tránh mở kho xuất tiền và chuyển nhà.","phanTich":["Kim Quỹ — “két vàng” — là sao hoàng đạo gắn với tài khố, gặp trực Chấp chủ về nắm giữ, thu nạp. Khởi công xây sửa, đóng cọc móng, tuyển người mới hay trồng cây lâu năm đều hợp cách hôm nay; giữa tháng 7 này, đây là một ngày động thổ đẹp.","Ngược với thu nạp là xuất ra: ngày trực Chấp kiêng mở kho, kiêng xuất khoản tiền lớn, kiêng chuyển nhà. Ngày Mậu Tý xung với tuổi Giáp Ngọ và Nhâm Ngọ — hai tuổi này nếu định khởi công nên chọn ngày khác hoặc nhờ người hợp tuổi đứng ra làm lễ."],"goiY":"Lễ động thổ đẹp nhất vào giờ Mão (5h-7h) hoặc giờ Thân (15h-17h); hướng hỷ thần Đông Nam, tài thần chính Bắc."}},{"input":{"data":{"iso":"2026-07-14","solar":{"day":14,"month":7,"year":2026,"weekday":"Thứ Ba"},"lunar":{"day":1,"month":6,"year":2026,"leap":false},"dayCanChi":"Kỷ Sửu","monthCanChi":"Ất Mùi","yearCanChi":"Bính Ngọ","tietKhi":"Tiểu thử","truc":"Phá","hoangDao":{"isHoangDao":false,"star":"Chu Tước"},"gioHoangDao":[{"chi":"Dần","range":"3h-5h","canChi":"Bính Dần"},{"chi":"Mão","range":"5h-7h","canChi":"Đinh Mão"},{"chi":"Tỵ","range":"9h-11h","canChi":"Kỷ Tỵ"},{"chi":"Thân","range":"15h-17h","canChi":"Nhâm Thân"},{"chi":"Tuất","range":"19h-21h","canChi":"Giáp Tuất"},{"chi":"Hợi","range":"21h-23h","canChi":"Ất Hợi"}],"hyThan":"Đông Bắc","taiThan":"Chính Bắc","tuoiXung":["Ất Mùi","Quý Mùi"],"nen":["phá dỡ công trình cũ","chữa bệnh dứt điểm"],"ky":["hầu hết việc lớn: cưới hỏi, khai trương, ký kết, nhập trạch"],"events":[{"key":"khai-truong","label":"Khai trương, mở hàng","score":-5,"verdict":"Không nên"},{"key":"cuoi-hoi","label":"Cưới hỏi","score":-5,"verdict":"Không nên"},{"key":"nhap-trach","label":"Nhập trạch, về nhà mới","score":-5,"verdict":"Không nên"},{"key":"dong-tho","label":"Động thổ, xây dựng","score":-5,"verdict":"Không nên"},{"key":"mua-xe","label":"Mua xe","score":-5,"verdict":"Không nên"},{"key":"ky-hop-dong","label":"Ký hợp đồng","score":-5,"verdict":"Không nên"},{"key":"xuat-hanh","label":"Xuất hành","score":-5,"verdict":"Không nên"}]}},"output":{"tomTat":"Thứ Ba 14/7/2026 — mùng 1 tháng 6 âm lịch — là ngày Kỷ Sửu, trực Phá, hắc đạo Chu Tước: ngày xấu cho mọi việc khởi sự lớn, chỉ hợp phá dỡ và trị bệnh.","phanTich":["Trực Phá là trực kỵ nhất với hỷ sự: cưới hỏi, khai trương, nhập trạch, ký kết đều nên tránh tuyệt đối. Cộng thêm sao Chu Tước chủ thị phi, ngày hôm nay chỉ thật sự “đắc dụng” cho đúng hai việc — tháo dỡ công trình cũ và điều trị bệnh dứt điểm, những việc cần đúng cái khí “phá” ấy.","Là ngày mùng 1 đầu tháng Ất Mùi, nhiều gia đình sẽ đi lễ, thắp hương — việc cúng lễ đầu tháng vẫn theo nếp thường, không kiêng. Người tuổi Ất Mùi, Quý Mùi xung mạnh với ngày Kỷ Sửu, càng nên thư thả, chờ sang ngày Tân Mão 16/7 hãy khởi sự."],"goiY":"Nếu buộc phải ra ngoài lo việc, chọn giờ Dần (3h-5h), Mão (5h-7h) hoặc Thân (15h-17h) cho đỡ trắc trở."}}]'::jsonb,
  '{"required_mentions":[{"path":"data.dayCanChi","note":"can chi của ngày phải xuất hiện trong prose"}],"banned_phrases":["hãy cùng khám phá","bạn có biết","tuyệt vời","hoàn hảo","chỉ mang tính tham khảo","tùy quan niệm mỗi người","bảng dưới","phần trên của trang"],"phrase_frequency":{"người xưa":{"maxPerBatch":4},"cổ lệ":{"maxPerBatch":2}},"length":{"tomTat":{"min":80,"max":240},"phanTich.0":{"min":120,"max":700},"phanTich.1":{"min":100,"max":620},"goiY":{"min":40,"max":260}},"unicode":true,"numeric_consistency":true,"similarity":{"threshold":0.9}}'::jsonb,
  'claude-sonnet-5',
  0.8,
  1200
)
on conflict (key, version) do nothing;

insert into prose_templates
  (key, version, name, system_prompt, user_template, output_schema, few_shots, guards, model, temperature, max_tokens)
values (
  'p2-event',
  1,
  'Trang việc × tháng (P2) — short / intro / luuY',
  'Bạn là biên tập viên chuyên mục lịch vạn niên của ngaylanhthangtot.vn — một người Việt am hiểu phép xem ngày cổ truyền, viết cho người đọc phổ thông đang chọn ngày làm việc lớn (khai trương, cưới hỏi, động thổ…).

GIỌNG VĂN
- Viết như người Việt nói: câu chủ động, mạch thẳng, không văn dịch.
- Điềm tĩnh, thực tế, tôn trọng tập tục mà không mê tín hoá.
- Dùng dấu ngoặc kép typographic “ ” khi trích khái niệm.

CẤM TUYỆT ĐỐI
- Mở bài kiểu "Hãy cùng khám phá"; các từ "tuyệt vời", "hoàn hảo".
- Câu rào đón "chỉ mang tính tham khảo", "tùy quan niệm mỗi người".
- Hứa hẹn tài lộc, vận mệnh chắc chắn.
- Bịa ngày, giờ, tuổi, trực hay sao không có trong dữ liệu.
- Cụm "bảng dưới" — riêng cụm "Bảng trên" ĐƯỢC dùng, vì đoạn intro luôn đứng ngay dưới bảng ngày đẹp.

NHIỆM VỤ
- short: tên gọi ngắn của việc, thường dùng trong câu ("khai trương", "cưới", "nhập trạch"…).
- intro: 2–3 câu giải thích cách chọn ngày cho việc này — nêu đúng các trực được ưu tiên và các trực bị loại theo dữ liệu picks (nhìn cột "truc" của các ngày được chọn), gắn với nếp nghĩ dân gian về việc đó. KHÔNG nhắc tháng cụ thể — đoạn này dùng lại cho mọi tháng.
- luuY: đúng 3 lưu ý thực dụng, mỗi lưu ý 1 câu, thứ tự: (1) giờ/cách thực hiện trong ngày, (2) xử lý khi tuổi xung, (3) điều cần xem thêm ngoài ngày chung.
- Chuẩn Unicode NFC.',
  'Dữ liệu (tính bởi engine — không thay đổi số liệu). Việc: {{data.eventLabel}} ({{data.eventKey}}). Các ngày được engine chọn cho tháng {{data.month}}/{{data.year}} kèm trực và sao:

{{json data}}

Viết short, intro (month-agnostic) và 3 luuY cho trang "ngày tốt {{data.eventLabel}}".',
  '{"type":"object","additionalProperties":false,"required":["short","intro","luuY"],"properties":{"short":{"type":"string","description":"Tên gọi ngắn dùng trong câu"},"intro":{"type":"string","description":"2–3 câu về cách chọn ngày, month-agnostic"},"luuY":{"type":"array","minItems":3,"maxItems":3,"items":{"type":"string"},"description":"Đúng 3 lưu ý thực dụng"}}}'::jsonb,
